import React, { useState } from "react";

function Features() {
  const [hoveredFeature, setHoveredFeature] = useState(null);

  const features = [
    {
      icon: "📊",
      title: "Student Dashboard",
      desc: "Track your progress, sessions, worksheets, and achievements all in one place. See your learning journey at a glance.",
      color: "#38bdf8"
    },
    {
      icon: "👨‍🏫",
      title: "Live Tutoring",
      desc: "Choose your tutor and join live sessions with reminders. Get personalized help when you need it most.",
      color: "#a855f7"
    },
    {
      icon: "📚",
      title: "Science Resources",
      desc: "Videos, downloads, and interactive tools to deepen your understanding of complex science concepts.",
      color: "#ec4899"
    },
    {
      icon: "📝",
      title: "Smart Worksheets",
      desc: "Practice with instant AI-powered analysis and personalized study suggestions tailored to your level.",
      color: "#38bdf8"
    },
    {
      icon: "🎮",
      title: "Science Games",
      desc: "Quick challenges that make learning fun and memorable. Compete with friends and earn achievements.",
      color: "#fbbf24"
    },
    {
      icon: "🤖",
      title: "SciPet AI",
      desc: "Your friendly study companion for questions, guidance, and motivation. Available 24/7 to support your learning.",
      color: "#a855f7"
    },
    {
      icon: "💬",
      title: "Public Chat Communities",
      desc: "Connect with peers in the community. Share knowledge, ask questions, and grow together as a learning community.",
      color: "#22c55e"
    },
    {
      icon: "🎯",
      title: "Personalized Learning Paths",
      desc: "Get customized lesson recommendations based on your strengths, weaknesses, and learning goals.",
      color: "#38bdf8"
    },
  ];

  return (
    <section className="page fade-in">
      <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "2rem" }}>
        {/* Header */}
        <div style={{ marginBottom: "4rem" }}>
          <h1 className="slide-up" style={{ fontSize: "2.5rem", marginBottom: "1rem", color: "#f9fafb" }}>
            Our Powerful Features
          </h1>
          <p className="slide-up" style={{ fontSize: "1.1rem", color: "#9ca3af", maxWidth: "600px", lineHeight: "1.7" }}>
            SciHub is packed with tools designed to make your science learning journey engaging, effective, and fun. Explore all the features we offer to help you succeed.
          </p>
        </div>

        {/* Features Grid */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: "2rem", marginBottom: "4rem" }}>
          {features.map((feature, i) => (
            <div
              key={i}
              className="card"
              onMouseEnter={() => setHoveredFeature(i)}
              onMouseLeave={() => setHoveredFeature(null)}
              style={{
                padding: "2.5rem",
                cursor: "pointer",
                transition: "all 0.3s ease",
                transform: hoveredFeature === i ? "translateY(-8px)" : "translateY(0)",
                boxShadow: hoveredFeature === i 
                  ? `0 20px 60px ${feature.color}30` 
                  : "0 10px 30px rgba(15, 23, 42, 0.5)",
                border: hoveredFeature === i 
                  ? `1px solid ${feature.color}` 
                  : "1px solid rgba(56, 189, 248, 0.3)",
                animation: `slideUp 0.6s ease forwards`,
                animationDelay: `${i * 0.08}s`,
                opacity: 0,
              }}
            >
              <div style={{ 
                fontSize: "2.8rem", 
                marginBottom: "1rem", 
                display: "inline-block", 
                transform: hoveredFeature === i ? "scale(1.2) rotate(10deg)" : "scale(1) rotate(0deg)", 
                transition: "transform 0.3s ease" 
              }}>
                {feature.icon}
              </div>
              <h3 style={{ fontSize: "1.4rem", marginTop: "0", marginBottom: "0.8rem", color: feature.color }}>
                {feature.title}
              </h3>
              <p style={{ color: "#9ca3af", marginBottom: "0", lineHeight: "1.6", fontSize: "0.95rem" }}>
                {feature.desc}
              </p>
            </div>
          ))}
        </div>

        {/* Why These Features Section */}
        <div style={{
          background: "linear-gradient(135deg, rgba(56, 189, 248, 0.1) 0%, rgba(168, 85, 247, 0.1) 100%)",
          border: "1px solid rgba(56, 189, 248, 0.3)",
          borderRadius: "20px",
          padding: "3rem 2rem",
          marginBottom: "4rem",
        }}>
          <h2 style={{ fontSize: "2rem", color: "#f9fafb", marginTop: "0", marginBottom: "2rem", textAlign: "center" }}>
            Why These Features?
          </h2>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: "2rem" }}>
            {[
              { title: "🎯 Comprehensive", desc: "From dashboards to games to AI companions, we cover every aspect of modern science learning." },
              { title: "🤖 AI-Powered", desc: "Smart worksheets and personalized paths adapt to your learning style and pace." },
              { title: "👥 Community-Driven", desc: "Learn together with peers through chat communities and collaborative study sessions." },
              { title: "📈 Progress Tracking", desc: "See real data about your improvement and get insights to guide your studies." },
            ].map((item, i) => (
              <div
                key={i}
                style={{
                  animation: `slideUp 0.6s ease forwards`,
                  animationDelay: `${i * 0.1}s`,
                  opacity: 0,
                }}
              >
                <h3 style={{ color: "#38bdf8", fontSize: "1.2rem", marginBottom: "0.8rem" }}>{item.title}</h3>
                <p style={{ color: "#9ca3af", lineHeight: "1.7", marginBottom: "0" }}>{item.desc}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Feature Highlights */}
        <div style={{
          background: "radial-gradient(circle at top left, rgba(168, 85, 247, 0.15) 0%, transparent 60%)",
          borderRadius: "20px",
          padding: "3rem 2rem",
          marginBottom: "4rem",
        }}>
          <h2 style={{ fontSize: "2rem", color: "#f9fafb", marginTop: "0", marginBottom: "2rem", textAlign: "center" }}>
            ✨ What Makes Us Different
          </h2>
          <div style={{ maxWidth: "800px", margin: "0 auto" }}>
            {[
              "Built by students, for students — we understand your challenges",
              "24/7 AI companion (SciPet) ready to help anytime",
              "Gamification keeps learning fun and motivating",
              "Real tutors paired with AI for the best of both worlds",
              "Community learning — study together, not alone",
              "Instant feedback on worksheets to accelerate improvement",
            ].map((item, i) => (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  marginBottom: "1.5rem",
                  animation: `slideUp 0.6s ease forwards`,
                  animationDelay: `${i * 0.08}s`,
                  opacity: 0,
                }}
              >
                <div style={{ 
                  fontSize: "1.5rem", 
                  marginRight: "1rem", 
                  minWidth: "30px" 
                }}>
                  ✨
                </div>
                <p style={{ color: "#f9fafb", fontSize: "1rem", lineHeight: "1.6", marginBottom: "0" }}>
                  {item}
                </p>
              </div>
            ))}
          </div>
        </div>
      </div>

      <style>{`
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </section>
  );
}

export default Features;
